-- paperclip:migration-compat online_compatible: the new skill_id column is nullable with no default and NULL in every existing row, so the previous release keeps reading and writing links (it never sets skill_id); the replacement single-target CHECK accepts every row the old one accepted and is swapped in one statement (catalog-only, brief lock) as NOT VALID, then validated under SHARE UPDATE EXCLUSIVE, which does not block reads or writes; the foreign key is added NOT VALID and validated the same way; both indexes are on the new column and are built CONCURRENTLY. Every statement is idempotent because this file runs outside a transaction.
ALTER TABLE "responsibility_links" ADD COLUMN IF NOT EXISTS "skill_id" uuid;--> statement-breakpoint
ALTER TABLE "responsibility_links" DROP CONSTRAINT IF EXISTS "responsibility_links_single_target_check", ADD CONSTRAINT "responsibility_links_single_target_check" CHECK (("responsibility_links"."project_id" is not null)::int + ("responsibility_links"."issue_id" is not null)::int + ("responsibility_links"."routine_id" is not null)::int + ("responsibility_links"."skill_id" is not null)::int = 1) NOT VALID;--> statement-breakpoint
ALTER TABLE "responsibility_links" VALIDATE CONSTRAINT "responsibility_links_single_target_check";--> statement-breakpoint
ALTER TABLE "responsibility_links" DROP CONSTRAINT IF EXISTS "responsibility_links_skill_id_company_skills_id_fk", ADD CONSTRAINT "responsibility_links_skill_id_company_skills_id_fk" FOREIGN KEY ("skill_id") REFERENCES "public"."company_skills"("id") ON DELETE cascade ON UPDATE no action NOT VALID;--> statement-breakpoint
ALTER TABLE "responsibility_links" VALIDATE CONSTRAINT "responsibility_links_skill_id_company_skills_id_fk";--> statement-breakpoint
CREATE UNIQUE INDEX CONCURRENTLY IF NOT EXISTS "responsibility_links_responsibility_skill_uq" ON "responsibility_links" USING btree ("responsibility_id","skill_id") WHERE "responsibility_links"."skill_id" is not null;--> statement-breakpoint
CREATE INDEX CONCURRENTLY IF NOT EXISTS "responsibility_links_skill_idx" ON "responsibility_links" USING btree ("skill_id");
